@using sv_a7a56703426945beba9b29b3983bddaf.Models

<div class="step-form">
    <h3>References</h3>
    <p class="form-hint">Please provide 2-3 professional references.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 1)"
                       OnChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="form-actions">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<Reference>
            {
                new("", "", "", ""),
                new("", "", "", "")
            };
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
            StateHasChanged();
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(References.ToList());
    }
}

@using sv_a7a56703426945beba9b29b3983bddaf.Models

<div class="step-form review-step">
    <h3>Review & Submit</h3>
    <p class="form-hint">Please review your application before submitting.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @if (IsSubmitted)
    {
        <div class="success-message">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <!-- Personal Info Section -->
        <div class="review-section">
            <div class="review-section-header">
                <h4>Personal Information</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <!-- Work History Section -->
        <div class="review-section">
            <div class="review-section-header">
                <h4>Work History</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="entry-description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <!-- References Section -->
        <div class="review-section">
            <div class="review-section-header">
                <h4>References</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />
                    <span>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</span>
                </div>
            }
        </div>

        <!-- Cover Letter Section -->
        <div class="review-section">
            <div class="review-section-header">
                <h4>Cover Letter</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="form-actions">
            <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        ErrorMessage = null;
        IsSubmitting = true;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

namespace sv_a7a56703426945beba9b29b3983bddaf.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_a7a56703426945beba9b29b3983bddaf.Models;

namespace sv_a7a56703426945beba9b29b3983bddaf.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300); // Simulate validation
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@using sv_a7a56703426945beba9b29b3983bddaf.Models

<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var cssClass = step == CurrentStep ? "active"
            : step < CurrentStep ? "completed"
            : "future";

        <button class="step @cssClass"
                disabled="@(step > CurrentStep)"
                @onclick="() => OnStepClicked(step)">
            @if (step < CurrentStep)
            {
                <span class="checkmark">&#10003;</span>
            }
            else
            {
                <span class="step-number">@(step + 1)</span>
            }
            <span class="step-label">@StepNames[step]</span>
        </button>

        @if (i < StepNames.Length - 1)
        {
            <span class="step-connector @(step < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@using sv_a7a56703426945beba9b29b3983bddaf.Models

<div class="step-form">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="Address" @bind:event="oninput" placeholder="Enter your address"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        { ErrorMessage = "Full name is required."; return; }
        if (string.IsNullOrWhiteSpace(Email))
        { ErrorMessage = "Email is required."; return; }
        if (string.IsNullOrWhiteSpace(Phone))
        { ErrorMessage = "Phone is required."; return; }
        if (string.IsNullOrWhiteSpace(Address))
        { ErrorMessage = "Address is required."; return; }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();
            var valid = await ValidateEmail(Email);
            IsValidating = false;
            if (!valid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

@using sv_a7a56703426945beba9b29b3983bddaf.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" />
        </div>
    </div>

    <div class="form-group checkbox-group">
        <label>
            <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" />
            Currently working here
        </label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? "" })"
                  placeholder="Describe your responsibilities..."></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(ChangeEventArgs e)
    {
        var current = (bool)(e.Value ?? false);
        var updated = current
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

@using sv_a7a56703426945beba9b29b3983bddaf.Models

<div class="step-form">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="form-actions">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
            Entries = new List<WorkEntry> { new("", "", DateTime.Today, null, "") };
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        StateHasChanged();
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries.ToList());
    }
}

