@page "/apply"
@using sv_a7a56703426945beba9b29b3983bddaf.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@personalFullName"
                                  Email="@personalEmail"
                                  Phone="@personalPhone"
                                  Address="@personalAddress"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="@references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnEditStep="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;

    // Personal info fields
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work history
    private List<WorkEntry> workEntries = new() { new("", "", DateTime.Today, null, "") };

    // References
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };

    // Cover letter
    private string coverLetter = "";

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoToStep(int step) => currentStep = step;
    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

